css:
/* El Costo Estándar (518) — clean rewrite v2.0.0. Dark theme, tokenized palette. */
.costo-sim-container {
  /* palette tokens */
  --cs-bg: #0f172a;
  --cs-panel: #1e293b;
  --cs-border: #334155;
  --cs-text: #e2e8f0;
  --cs-text-strong: #f1f5f9;
  --cs-muted: #94a3b8;
  --cs-muted-2: #64748b;
  --cs-accent: #3b82f6;
  --cs-accent-hover: #2563eb;
  --cs-accent-light: #60a5fa;
  --cs-favorable: #22c55e;
  --cs-unfavorable: #ef4444;
  --cs-k-budget: #3b82f6;
  --cs-k-waste: #f59e0b;
  --cs-k-efficiency: #8b5cf6;
  --cs-k-variance: #ef4444;
  --cs-radius: 6px;
  --cs-gap: 20px;

  padding: 24px;
  min-height: 100vh;
  background: var(--cs-bg);
  color: var(--cs-text);
  font-family: -apple-system, 'Segoe UI', 'Inter', sans-serif;
}

/* Reusable panel surface */
.costo-sim-header,
.costo-sim-period-bar,
.costo-sim-briefing,
.costo-sim-kpi-card,
.costo-sim-market-strip,
.costo-sim-controls,
.costo-sim-results-panel,
.costo-sim-chart-section,
.costo-sim-history {
  background: var(--cs-panel);
  border: 1px solid var(--cs-border);
  border-radius: var(--cs-radius);
  margin-bottom: var(--cs-gap);
}

/* Header */
.costo-sim-header {
  border-left: 5px solid var(--cs-accent);
  padding: 28px 32px;
}
.costo-sim-header-badge {
  display: inline-block;
  margin-bottom: 12px;
  padding: 4px 12px;
  font-size: 0.72rem;
  letter-spacing: 0.1em;
  text-transform: uppercase;
  color: var(--cs-accent-light);
  background: rgba(59, 130, 246, 0.15);
  border: 1px solid rgba(59, 130, 246, 0.3);
  border-radius: 3px;
}
.costo-sim-header h1 {
  margin: 0 0 6px;
  font-size: 1.6rem;
  font-weight: 700;
  color: var(--cs-text-strong);
}
.costo-sim-subtitle {
  margin: 0;
  font-size: 0.9rem;
  color: var(--cs-muted);
}

/* Period bar */
.costo-sim-period-bar {
  display: flex;
  align-items: center;
  gap: 6px;
  padding: 12px 20px;
  font-size: 0.95rem;
  color: var(--cs-muted);
}
.costo-sim-period-num {
  color: var(--cs-text-strong);
  font-weight: 700;
}
.costo-sim-period-name {
  margin-left: auto;
  color: var(--cs-accent-light);
  font-weight: 600;
}

/* Briefing */
.costo-sim-briefing { padding: 20px 24px; }
.costo-sim-briefing-title {
  margin-bottom: 10px;
  font-size: 0.72rem;
  letter-spacing: 0.1em;
  text-transform: uppercase;
  color: var(--cs-muted-2);
}
.costo-sim-container #briefingText {
  font-size: 0.88rem;
  line-height: 1.6;
  color: #cbd5e1;
}

/* KPI grid */
.costo-sim-kpi-grid {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 14px;
  background: none;
  border: none;
}
.costo-sim-kpi-card {
  position: relative;
  overflow: hidden;
  padding: 18px 16px;
  margin-bottom: 0;
}
.costo-sim-kpi-card::before {
  content: '';
  position: absolute;
  inset: 0 0 auto 0;
  height: 3px;
  background: var(--cs-kpi-accent, var(--cs-accent));
}
.costo-sim-kpi--budget { --cs-kpi-accent: var(--cs-k-budget); }
.costo-sim-kpi--waste { --cs-kpi-accent: var(--cs-k-waste); }
.costo-sim-kpi--efficiency { --cs-kpi-accent: var(--cs-k-efficiency); }
.costo-sim-kpi--variance { --cs-kpi-accent: var(--cs-k-variance); }
.costo-sim-kpi-icon { margin-bottom: 6px; font-size: 1.2rem; }
.costo-sim-kpi-label {
  margin-bottom: 8px;
  font-size: 0.7rem;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  color: var(--cs-muted-2);
}
.costo-sim-kpi-value {
  font-size: 1.5rem;
  font-weight: 700;
  color: var(--cs-text-strong);
}
.costo-sim-kpi-target {
  margin-top: 6px;
  font-size: 0.72rem;
  font-style: italic;
  color: var(--cs-muted-2);
}

/* Market strip */
.costo-sim-market-strip {
  display: flex;
  flex-wrap: wrap;
  justify-content: space-between;
  gap: 12px;
  padding: 10px 20px;
  font-size: 0.82rem;
  color: var(--cs-muted);
}
.costo-sim-market-item span:last-child {
  color: var(--cs-text);
  font-weight: 600;
}

/* Controls */
.costo-sim-controls { padding: 24px; }
.costo-sim-controls h3 {
  margin: 0 0 18px;
  padding-bottom: 10px;
  font-size: 1rem;
  font-weight: 600;
  color: var(--cs-text-strong);
  border-bottom: 1px solid var(--cs-border);
}
.costo-sim-controls-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 20px;
  margin-bottom: 20px;
}
.costo-sim-control-group label {
  display: block;
  margin-bottom: 8px;
  font-size: 0.8rem;
  font-weight: 500;
  color: var(--cs-muted);
}
.costo-sim-control-group input[type="number"],
.costo-sim-control-group select {
  width: 100%;
  padding: 10px 12px;
  font-size: 0.95rem;
  color: var(--cs-text);
  background: var(--cs-bg);
  border: 1px solid #475569;
  border-radius: 4px;
  transition: border-color 0.2s ease, box-shadow 0.2s ease;
}
.costo-sim-control-group input:focus,
.costo-sim-control-group select:focus {
  outline: none;
  border-color: var(--cs-accent);
  box-shadow: 0 0 0 2px rgba(59, 130, 246, 0.2);
}
.costo-sim-control-hint {
  margin-top: 6px;
  font-size: 0.7rem;
  line-height: 1.4;
  color: var(--cs-muted-2);
}

/* Buttons */
.costo-sim-btn-row { display: flex; align-items: center; gap: 12px; }
.costo-sim-btn-submit {
  padding: 10px 28px;
  font-size: 0.9rem;
  font-weight: 600;
  color: #fff;
  background: var(--cs-accent);
  border: none;
  border-radius: 4px;
  cursor: pointer;
  transition: background 0.2s ease;
}
.costo-sim-btn-submit:hover { background: var(--cs-accent-hover); }
.costo-sim-btn-undo {
  padding: 8px 16px;
  font-size: 0.8rem;
  color: var(--cs-muted);
  background: transparent;
  border: 1px solid #475569;
  border-radius: 4px;
  cursor: pointer;
  transition: border-color 0.2s ease, color 0.2s ease;
}
.costo-sim-btn-undo:hover { border-color: var(--cs-muted); color: var(--cs-text); }

/* Results panel */
.costo-sim-results-panel { padding: 24px; }
.costo-sim-results-panel h3 {
  margin: 0 0 16px;
  font-size: 1rem;
  font-weight: 600;
  color: var(--cs-text-strong);
}
.costo-sim-variance-grid {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 12px;
  margin-bottom: 16px;
}
.costo-sim-variance-card {
  padding: 14px 12px;
  text-align: center;
  background: var(--cs-bg);
  border: 1px solid var(--cs-border);
  border-radius: 4px;
}
.costo-sim-variance-label {
  margin-bottom: 8px;
  font-size: 0.68rem;
  letter-spacing: 0.06em;
  text-transform: uppercase;
  color: var(--cs-muted-2);
}
.costo-sim-variance-value { font-size: 1.1rem; font-weight: 700; }
.costo-sim-var-favorable { color: var(--cs-favorable); }
.costo-sim-var-unfavorable { color: var(--cs-unfavorable); }
.costo-sim-net-variance {
  padding: 12px;
  text-align: center;
  font-size: 0.9rem;
  color: var(--cs-muted);
  background: var(--cs-bg);
  border-radius: 4px;
}
.costo-sim-net-value { margin-left: 8px; font-size: 1.3rem; font-weight: 700; }

/* Chart + history */
.costo-sim-chart-section,
.costo-sim-history { padding: 24px; }
.costo-sim-chart-section h3,
.costo-sim-history h3 {
  margin: 0 0 16px;
  font-size: 1rem;
  font-weight: 600;
  color: var(--cs-text-strong);
}
.costo-sim-chart-wrapper { position: relative; height: 280px; }
.costo-sim-container .table {
  font-size: 0.82rem;
  color: #cbd5e1;
  background: transparent;
}
.costo-sim-container .table th {
  font-size: 0.72rem;
  font-weight: 600;
  letter-spacing: 0.05em;
  text-transform: uppercase;
  color: var(--cs-muted);
  background: var(--cs-bg);
  border-color: var(--cs-border);
}
.costo-sim-container .table td {
  padding: 10px 12px;
  border-color: var(--cs-border);
}
.costo-sim-container .table tbody tr:hover { background: rgba(59, 130, 246, 0.05); }

/* Responsive */
@media (max-width: 768px) {
  .costo-sim-container { padding: 14px; }
  .costo-sim-kpi-grid { grid-template-columns: repeat(2, 1fr); }
  .costo-sim-controls-grid { grid-template-columns: 1fr; }
  .costo-sim-variance-grid { grid-template-columns: repeat(2, 1fr); }
  .costo-sim-market-strip { flex-direction: column; gap: 6px; }
  .costo-sim-kpi-value { font-size: 1.2rem; }
}

