              briefingEs: 'El algodón sube 5% por inundaciones en campos de algodón en Brasil. Las exportaciones de uniformes a Centroamérica aumentan la presión sobre la planta. El CFO solicita un informe de progreso sobre la reducción de varianzas.',
              briefingEn: 'Cotton surges 5% due to flooding in Brazilian cotton fields. Uniform exports to Central America increase plant pressure. The CFO requests a progress report on variance reduction.'
          },
          {
              name: 'Julio 2026',
              nameEn: 'July 2026',
              cottonShock: -0.01,
              briefingEs: 'Último mes del programa de mejora. El algodón se estabiliza con una ligera baja. La junta evaluará los resultados acumulados de Q2 para decidir si se mantiene el presupuesto de mejora en Q3 o se ajustan los estándares.',
              briefingEn: 'Final month of the improvement program. Cotton stabilizes with a slight dip. The board will evaluate cumulative Q2 results to decide whether to maintain the improvement budget in Q3 or adjust standards.'
          }
      ];

      // transient render bookkeeping (never persisted)
      this._lastRenderedPeriod = 0;
      this._wired = false;
    }

    /* ============================== lifecycle ============================== */

    initialize(state) {
      if (!state.domainState || Object.keys(state.domainState).length === 0) {
        state.domainState = this._freshDomainState();
      }
      if (!state.decisions || Object.keys(state.decisions).length === 0) {
        state.decisions = { maintenanceBudget: 0, trainingBudget: 0, purchaseStrategy: STRATEGY.SPOT };
      }
      this._renderMonth(state.currentPeriod || 1);
    }

    validateDecisions(decisions) {
      var maint = this._readNumber('maintenanceInput');
      var train = this._readNumber('trainingInput');
      decisions.maintenanceBudget = maint;
      decisions.trainingBudget = train;
      decisions.purchaseStrategy = this._readInt('strategySelect', STRATEGY.SPOT);

      if (maint < 0 || maint > 15) return this._reject('maint_warning');
      if (train < 0 || train > 10) return this._reject('training_warning');

      var ds = window.mySimulation.state.domainState;
      var remaining = ds ? ds.improvementBudget : this.START_BUDGET;
      if (maint + train > remaining) return this._reject('budget_warning');
      return true;
    }

    calculateResults(state) {
      var d = state.decisions;
      var ds = state.domainState;
      var month = this.MONTHS[this._monthIndex(state.currentPeriod)];

      // 1) Spend the budget and accumulate investment.
      var spend = d.maintenanceBudget + d.trainingBudget;
      ds.maintenanceAccum += d.maintenanceBudget;
      ds.trainingAccum += d.trainingBudget;
      ds.improvementBudget -= spend;
      ds.totalSpent += spend;

      // 2) Recompute operating rates from cumulative investment.
      ds.wasteRate = this._wasteRate(ds.maintenanceAccum);
      ds.hoursPerUnit = this._hoursPerUnit(ds.trainingAccum, state.currentPeriod);

      // 3) Resolve the cotton price actually paid (market, or locked forward + premium).
      var marketPrice = Math.round(ds.cottonPrice * (1 + month.cottonShock + (Math.random() - 0.5) * 0.02));
      var effectivePrice = this.FORWARD_PREMIUM[d.purchaseStrategy]
        ? Math.round(ds.cottonPrice * this.FORWARD_PREMIUM[d.purchaseStrategy])
        : marketPrice;
      ds.cottonPrice = marketPrice;

      // 4) Four standard-cost variances (favorable <= 0, unfavorable > 0).
      var actualMaterialQty = this.PRODUCTION * ds.wasteRate;
      var stdMaterialQty    = this.PRODUCTION * this.STD_MATERIAL_PER_UNIT;
      var matQtyVariance    = Math.round((actualMaterialQty - stdMaterialQty) * this.STD_COTTON_PRICE);
      var matPriceVariance  = Math.round(actualMaterialQty * (effectivePrice - this.STD_COTTON_PRICE));

      var actualHours     = this.PRODUCTION * ds.hoursPerUnit;
      var stdHours        = this.PRODUCTION * this.STD_HOURS_PER_UNIT;
      var labEffVariance  = Math.round((actualHours - stdHours) * this.STD_LABOR_RATE);
      var rateDeviation   = (Math.random() - 0.5) * 100;
      var labRateVariance = Math.round(actualHours * rateDeviation);

      var netVariance = matQtyVariance + matPriceVariance + labEffVariance + labRateVariance;

      // 5) Record history for the KPIs, chart, table and end-of-run report.
      ds.cumulativeNetVariance += netVariance;
      ds.matQtyHistory.push(matQtyVariance);
      ds.matPriceHistory.push(matPriceVariance);
      ds.labEffHistory.push(labEffVariance);
      ds.labRateHistory.push(labRateVariance);
      ds.netVarianceHistory.push(netVariance);
      ds.budgetRemainingHistory.push(ds.improvementBudget);

      // Platform score: same tier ladder getPerformanceSummary uses (good/excellent/expert gated
      // on cumulativeNetVariance under 200M/100M/50M COP plus the same waste/hours thresholds),
      // evaluated on the running totals; interpolated within its band so the score moves each round.
      var wasteOk105 = ds.wasteRate <= 0.105, hoursOk865 = ds.hoursPerUnit <= 0.865;
      var wasteOk085 = ds.wasteRate <= 0.085, hoursOk855 = ds.hoursPerUnit <= 0.855;
      var tierLevel = 0;
      if (ds.cumulativeNetVariance < 200000000 && (wasteOk105 || hoursOk865)) tierLevel = 1;
      if (ds.cumulativeNetVariance < 100000000 && wasteOk105 && hoursOk865) tierLevel = 2;
      if (ds.cumulativeNetVariance < 50000000 && wasteOk085 && hoursOk855) tierLevel = 3;
      var overallScore;
      if (tierLevel === 3) overallScore = 90 + Math.round(Math.min(10, Math.max(0, (50000000 - ds.cumulativeNetVariance) / 5000000)));
      else if (tierLevel === 2) overallScore = 70 + Math.round(Math.min(19, Math.max(0, (100000000 - ds.cumulativeNetVariance) / 5000000)));
      else if (tierLevel === 1) overallScore = 50 + Math.round(Math.min(19, Math.max(0, (200000000 - ds.cumulativeNetVariance) / 10000000)));
      else overallScore = Math.round(Math.max(0, 50 - (ds.cumulativeNetVariance - 200000000) / 20000000));
      overallScore = Math.max(0, Math.min(100, overallScore));
      state.domainState.performance = Object.assign({}, state.domainState.performance || {}, { overallScore: overallScore });

      this._renderVarianceCards(matQtyVariance, matPriceVariance, labEffVariance, labRateVariance, netVariance);
      this._showResults(true);

      return {
        period: state.currentPeriod,
        maintenanceBudget: d.maintenanceBudget,
        trainingBudget: d.trainingBudget,
        purchaseStrategy: d.purchaseStrategy,
        matQtyVariance: matQtyVariance,
        matPriceVariance: matPriceVariance,
        labEffVariance: labEffVariance,
        labRateVariance: labRateVariance,
        netVariance: netVariance,
        wasteRate: ds.wasteRate,
        hoursPerUnit: ds.hoursPerUnit,
        cottonPrice: effectivePrice,
        budgetRemaining: ds.improvementBudget,
        cumulativeNetVariance: ds.cumulativeNetVariance
      };
    }

    /* =============================== model =============================== */

    _monthIndex(period) {
      return Math.min(Math.max((period || 1) - 1, 0), this.MONTHS.length - 1);
    }

    // Waste starts at START_WASTE_RATE and is driven toward the STD_MATERIAL_PER_UNIT
    // standard by cumulative maintenance (fully removed at MAINT_FULL_EFFECT_AT).
    _wasteRate(maintenanceAccum) {
      var reduction = Math.min(maintenanceAccum / this.MAINT_FULL_EFFECT_AT, 1.0);
      var excess = this.START_WASTE_RATE - this.STD_MATERIAL_PER_UNIT;
      return Math.max(this.STD_MATERIAL_PER_UNIT + excess * (1 - reduction), this.STD_MATERIAL_PER_UNIT);
    }

    // Hours start at START_HOURS_PER_UNIT and fall toward STD_HOURS_PER_UNIT via
    // training (capped at TRAIN_MAX_EFFECT) plus a small natural learning curve.
    _hoursPerUnit(trainingAccum, period) {
      var naturalLearning = Math.min((period || 1) * 0.005, 0.03);
      var trainEffect = Math.min(trainingAccum / this.TRAIN_FULL_EFFECT_AT, this.TRAIN_MAX_EFFECT);
      var excess = this.START_HOURS_PER_UNIT - this.STD_HOURS_PER_UNIT;
      return this.STD_HOURS_PER_UNIT + Math.max(excess * (1 - trainEffect) - naturalLearning, 0);
    }

    _freshDomainState() {
      return {
        improvementBudget: this.START_BUDGET,
        totalSpent: 0,
        wasteRate: this.START_WASTE_RATE,
        hoursPerUnit: this.START_HOURS_PER_UNIT,
        cottonPrice: this.START_COTTON_PRICE,
        cumulativeNetVariance: 0,
        maintenanceAccum: 0,
        trainingAccum: 0,
        matQtyHistory: [],
        matPriceHistory: [],
        labEffHistory: [],
        labRateHistory: [],
        netVarianceHistory: [],
        budgetRemainingHistory: []
      };
    }

    /* ============================ UI bindings ============================ */

    setupUI(uiManager) {
      uiManager.bind('currentDay', 'currentPeriod');
      uiManager.bind('maxPeriods', 'maxPeriods');
      uiManager.bind('budgetDisplay', 'domainState.improvementBudget', function (v) { return 'COP ' + Math.round(v) + 'M'; });
      uiManager.bind('wasteDisplay', 'domainState.wasteRate', function (v) { return (v * 100).toFixed(1) + '%'; });
      uiManager.bind('efficiencyDisplay', 'domainState.hoursPerUnit', function (v) { return v.toFixed(3); });
      uiManager.bind('cumVarianceDisplay', 'domainState.cumulativeNetVariance', function (v) { return (v <= 0 ? '' : '+') + 'COP ' + (v / 1000000).toFixed(1) + 'M'; });
      uiManager.bind('cottonPriceDisplay', 'domainState.cottonPrice', function (v) { return 'COP ' + Math.round(v).toLocaleString() + '/kg'; });
      this._wireFrameworkEvents();
    }

    getChartConfig() {
      var t = this._t();
      var axis = { ticks: { color: '#94a3b8' }, grid: { color: 'rgba(51,65,85,0.5)' } };
      var series = function (labelKey, color) {
        return { label: t(labelKey), data: [], backgroundColor: color + 'b3', borderColor: color, borderWidth: 1 };
      };
      return {
        varianceChart: {
          type: 'bar',
          data: {
            labels: [],
            datasets: [
              series('var_mat_qty', '#ef4444'),
              series('var_mat_price', '#f97316'),
              series('var_lab_eff', '#8b5cf6'),
              series('var_lab_rate', '#3b82f6')
            ]
          },
          options: {
            responsive: true,
            maintainAspectRatio: false,
            plugins: {
              title: { display: false },
              legend: { labels: { color: '#94a3b8', font: { size: 11 } } }
            },
            scales: {
              x: axis,
              y: {
                ticks: { color: '#94a3b8', callback: function (v) { return (v / 1000000).toFixed(0) + 'M'; } },
                grid: { color: 'rgba(51,65,85,0.5)' }
              }
            }
          }
        }
      };
    }

    getChartData(state) {
      var ds = state.domainState;
      var prefix = this._t()('period_label');
      var labels = ds.netVarianceHistory.map(function (_, i) { return prefix + ' ' + (i + 1); });
      return {
        varianceChart: {
          labels: labels,
          datasets: [
            { data: ds.matQtyHistory },
            { data: ds.matPriceHistory },
            { data: ds.labEffHistory },
            { data: ds.labRateHistory }
          ]
        }
      };
    }

    getHistoryTableConfig() {
      var copM = function (v) { return 'COP ' + v + 'M'; };
      var copMM = function (v) { return 'COP ' + (v / 1000000).toFixed(1) + 'M'; };
      return [
        { key: 'decisions.maintenanceBudget', i18nKey: 'col_maintenance', label: 'Mant. (M)', formatter: copM },
        { key: 'decisions.trainingBudget', i18nKey: 'col_training', label: 'Capac. (M)', formatter: copM },
        { key: 'results.matQtyVariance', i18nKey: 'col_matqty', label: 'V. Cant. Mat.', formatter: copMM },
        { key: 'results.matPriceVariance', i18nKey: 'col_matprice', label: 'V. Precio Mat.', formatter: copMM },
        { key: 'results.labEffVariance', i18nKey: 'col_labeff', label: 'V. Efic. M.O.', formatter: copMM },
        { key: 'results.netVariance', i18nKey: 'col_net', label: 'V. Neta', formatter: copMM },
        { key: 'results.wasteRate', i18nKey: 'col_waste', label: 'Desperdicio', formatter: function (v) { return (v * 100).toFixed(1) + '%'; } },
        { key: 'results.hoursPerUnit', i18nKey: 'col_hours', label: 'Hrs/Unid', formatter: function (v) { return v.toFixed(3); } }
      ];
    }

    getPresets() { return null; }

    /* ===================== hints & performance summary ===================== */

    getHint(state, results) {
      if (!results) return null;
      var t = this._t();
      var ds = state.domainState;
      if (results.netVariance > 100000000) return t('hint_high_variance');
      if (ds.improvementBudget < 5 && state.currentPeriod < 4) return t('hint_low_budget');
      if (results.matQtyVariance > 50000000 && ds.maintenanceAccum < 5) return t('hint_need_maintenance');
      if (results.labEffVariance > 100000000 && ds.trainingAccum < 3) return t('hint_need_training');
      if (results.netVariance <= 0) return t('hint_favorable');
      return null;
    }

    getPerformanceSummary(history) {
      var t = this._t();
      if (!history || !history.length) return { totalPeriods: 0 };

      var totalNet = 0, totalSpent = 0;
      for (var i = 0; i < history.length; i++) {
        var r = history[i].results || {};
        totalNet += r.netVariance || 0;
        totalSpent += (r.maintenanceBudget || 0) + (r.trainingBudget || 0);
      }
      var last = history[history.length - 1].results || {};
      var lastWaste = last.wasteRate != null ? last.wasteRate : this.START_WASTE_RATE;
      var lastHours = last.hoursPerUnit != null ? last.hoursPerUnit : this.START_HOURS_PER_UNIT;
      var wasteImproved = lastWaste <= 0.105;
      var effImproved = lastHours <= 0.865;

      var perfKey = 'perf_needs';
      if (totalNet < 200000000 && (wasteImproved || effImproved)) perfKey = 'perf_good';
      if (totalNet < 100000000 && wasteImproved && effImproved) perfKey = 'perf_excellent';
      if (totalNet < 50000000 && lastWaste <= 0.085 && lastHours <= 0.855) perfKey = 'perf_expert';

      var insights = [];
      if (lastWaste <= 0.085) insights.push(t('insight_waste_lo'));
      else if (lastWaste <= 0.10) insights.push(t('insight_waste_mid'));
      else insights.push(t('insight_waste_hi'));
      if (lastHours <= 0.855) insights.push(t('insight_hours_lo'));
      else if (lastHours <= 0.87) insights.push(t('insight_hours_mid'));
      else insights.push(t('insight_hours_hi'));

      return {
        totalPeriods: history.length,
        totalNetVariance: totalNet,
        totalInvested: totalSpent,
        finalWasteRate: lastWaste,
        finalHoursPerUnit: lastHours,
        performance: t(perfKey),
        insights: insights,
        message: t(perfKey)
      };
    }

    formatCompletionMessage(summary) {
      var t = this._t();
      var s = summary || {};
      var net = s.totalNetVariance != null ? s.totalNetVariance : 0;
      var netStr = (net <= 0 ? '' : '+') + 'COP ' + (net / 1000000).toFixed(1) + 'M';
      var netColor = net <= 0 ? '#22c55e' : '#ef4444';
      var row = function (label, value, color) {
        return '<div style="display:flex;justify-content:space-between;padding:6px 2px;border-bottom:1px solid #334155;">' +
          '<span style="color:#94a3b8;">' + label + '</span>' +
          '<span style="font-weight:700;color:' + (color || '#f1f5f9') + ';">' + value + '</span></div>';
      };
      var items = (s.insights || []).map(function (x) { return '<li style="margin-bottom:6px;">' + x + '</li>'; }).join('');
      return '<div style="padding:8px 4px;text-align:left;max-width:440px;margin:0 auto;color:#e2e8f0;">' +
        '<h4 style="text-align:center;color:#f1f5f9;margin:0 0 16px;">' + t('summary_title') + '</h4>' +
        row(t('summary_netvar'), netStr, netColor) +
        row(t('summary_invested'), 'COP ' + (s.totalInvested != null ? s.totalInvested : 0) + 'M') +
        row(t('summary_finalwaste'), ((s.finalWasteRate != null ? s.finalWasteRate : 0) * 100).toFixed(1) + '%') +
        row(t('summary_finalhours'), (s.finalHoursPerUnit != null ? s.finalHoursPerUnit : 0).toFixed(3)) +
        row(t('summary_perf'), '<b>' + (s.performance || '') + '</b>', '#60a5fa') +
        '<ul style="margin:14px 0 0;padding-left:18px;line-height:1.5;color:#cbd5e1;">' + items + '</ul>' +
        '</div>';
    }

    /* ===================== rendering & framework events ===================== */

    _renderMonth(periodNum) {
      var month = this.MONTHS[this._monthIndex(periodNum)];
      var en = this._lang() === 'en';
      var briefing = document.getElementById('briefingText');
      if (briefing) briefing.innerHTML = en ? month.briefingEn : month.briefingEs;
      var name = document.getElementById('monthName');
      if (name) name.textContent = en ? month.nameEn : month.name;
      this._lastRenderedPeriod = this._monthIndex(periodNum) + 1;
    }

    _renderVarianceCards(matQty, matPrice, labEff, labRate, net) {
      var cards = [
        ['matQtyVariance', matQty],
        ['matPriceVariance', matPrice],
        ['labEffVariance', labEff],
        ['labRateVariance', labRate]
      ];
      for (var i = 0; i < cards.length; i++) this._setVariance(cards[i][0], cards[i][1], 'costo-sim-variance-value');
      this._setVariance('netVarianceDisplay', net, 'costo-sim-net-value');
    }

    _setVariance(id, value, baseClass) {
      var el = document.getElementById(id);
      if (!el) return;
      el.textContent = (value <= 0 ? '' : '+') + 'COP ' + (value / 1000000).toFixed(1) + 'M';
      el.className = baseClass + ' ' + (value <= 0 ? 'costo-sim-var-favorable' : 'costo-sim-var-unfavorable');
    }

    _showResults(show) {
      var panel = document.getElementById('resultsPanel');
      if (panel) panel.style.display = show ? 'block' : 'none';
    }

    _wireFrameworkEvents() {
      if (this._wired) return;
      var sim = window.mySimulation;
      if (!sim || !sim.eventBus) return;
      var self = this;
      sim.eventBus.on('period:submitted', function () { self._onPeriodSubmitted(); });
      sim.eventBus.on('period:undone', function () { self._onPeriodUndone(); });
      document.addEventListener('express:langchanged', function () {
        var live = (window.mySimulation && window.mySimulation.state) ? window.mySimulation.state.currentPeriod : 1;
        self._lastRenderedPeriod = 0;
        self._renderMonth(live);
      });
      this._wired = true;
    }

    // The framework advances currentPeriod AFTER grading; render the new month's
    // briefing while leaving the results panel visible so the player can read it.
    _onPeriodSubmitted() {
      var state = window.mySimulation && window.mySimulation.state;
      if (!state) return;
      var live = state.currentPeriod;
      if (typeof live === 'number' && live > this._lastRenderedPeriod && live <= this.MONTHS.length) {
        this._renderMonth(live);
      }
    }

    // Undoing the first month empties history; the framework's initialize() guard
    // won't reset a non-empty domainState, so reset it here for a clean replay.
    _onPeriodUndone() {
      var sim = window.mySimulation;
      if (!sim || !sim.state) return;
      if (!sim.state.history || sim.state.history.length === 0) {
        sim.state.domainState = this._freshDomainState();
        try { sim.updateUI(); } catch (e) {}
        this._showResults(false);
      }
      this._lastRenderedPeriod = 0;
      this._renderMonth(sim.state.currentPeriod || 1);
    }

    /* =============================== helpers =============================== */

    _lang() {
      if (window.vcI18n && window.vcI18n._lang) return window.vcI18n._lang;
      var htmlLang = (document.documentElement && document.documentElement.lang) || 'es';
      return htmlLang.split('-')[0].toLowerCase();
    }

    _t() {
      return (window.mySimulation && window.mySimulation.t)
        ? window.mySimulation.t.bind(window.mySimulation)
        : function (k) { return k; };
    }

    _readNumber(id) {
      var el = document.getElementById(id);
      return el ? (parseFloat(el.value) || 0) : 0;
    }

    _readInt(id, fallback) {
      var el = document.getElementById(id);
      return el ? (parseInt(el.value, 10) || fallback) : fallback;
    }

    _reject(msgKey) {
      window.mySimulation.uiManager.showNotification(window.mySimulation.t(msgKey), 'warning');
      return false;
    }

